using System;
using System.Drawing;
using System.Linq;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using System.Runtime.InteropServices;
using System.Windows.Forms;
namespace Overclock {
 sealed partial class MainWindow {
  BenchmarkResults results;StorageCapacity capacitySnapshot;string capacityRaw="";
  [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr window,int attribute,ref int value,int size);
  protected override void OnHandleCreated(EventArgs args){base.OnHandleCreated(args);try{int dark=1;DwmSetWindowAttribute(Handle,20,ref dark,4);}catch{}}
  void BuildTabs(){foreach(Control c in tabs.Controls.Cast<Control>().ToArray())c.Dispose();tabs.Controls.Clear();string group=new[]{"CPU","GPU","Memory","Storage","Drive Health","Sensors","Inventory","Network"}.Contains(page)?"Hardware":page.EndsWith("Benchmark")?"Storage tests":page=="GPU Stress Test"?"GPU stress":page;foreach(var b in navButtons){b.Value.Selected=b.Key==group;b.Value.Invalidate();}string[] names=group=="Hardware"?new[]{"CPU","GPU","Memory","Storage","Drive Health","Sensors","Inventory"}:group=="Storage tests"?new[]{"Disk Benchmark","AS SSD Benchmark","Copy Benchmark","Compression Benchmark"}:new string[0];tabs.Visible=!compact&&names.Length>0;foreach(string name in names){string destination=name;var b=(ModernButton)Theme.Button(name.Replace(" Benchmark",""));b.Width=group=="Hardware"?(name=="Drive Health"?120:name=="Inventory"?110:100):name=="Compression Benchmark"?155:120;b.Selected=page==name;b.Click+=(s,e)=>Navigate(destination);tabs.Controls.Add(b);}subtitle.Text=compact?"Live hardware at a glance":page=="Overview"?"Your system, in focus.   Live telemetry and recent activity.":group=="Storage tests"?"Choose a drive and preset. Advanced settings stay out of the way.":page=="Sensors"?"Explore hardware readings. Select a row to see its history.":page=="Drive Health"?"Drive condition, temperatures and warnings — without the data dump.":page=="GPU Stress Test"?"Independent OpenGL workload with temperature protection.":page=="Reports"?"Your benchmark history. Compare matching workloads and export results.":"Live hardware information, clearly organized.";results=null;}
  void UpdateResultContext(object sender,EventArgs args){if(results!=null&&!results.IsDisposed)results.SetContext(disks.Text,page=="Copy Benchmark"?"Copy":profile.Text,size.Text,duration.Text,repeats.Text);}
  string Metric(string key,string prefix){string l=sources[key].Value.Split('\n').FirstOrDefault(v=>v.StartsWith(prefix));return l==null?"—":l.Substring(prefix.Length).Trim().TrimEnd('\r');}
  void UpdateCards(){string incoming=sources["Capacity"].Value;if(incoming!=capacityRaw){capacityRaw=incoming;try{capacitySnapshot=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<StorageCapacity>(incoming);}catch{capacitySnapshot=null;}}foreach(var pair in tiles){string key=pair.Key;var tile=pair.Value;string primary="—",unit="",device="",secondary="",foot="Open details  →",ring="—";float level=-1;float[] series=new float[0];if(key=="CPU"||key=="GPU"){string prefix=key=="CPU"?"CPU load":"Load";float load=ReadMetric(sources[key].Value,prefix);primary=load>=0?load.ToString("0")+"%":"—";unit="utilization";device=key=="CPU"?sources[key].Value.Split('\n').Skip(1).FirstOrDefault()??"Detecting processor":sources[key].Value.Split('\n').FirstOrDefault()??"Detecting graphics";if(key=="GPU"){ring=Metric("GPU","Temperature").Replace("°C","°").Replace(" ","");secondary="Power "+Metric("GPU","Power")+"   ·   "+Metric("GPU","Clock");float t;if(float.TryParse(Regex.Match(ring,@"[0-9.]+").Value,out t))level=t; }else{var t=sensorClient.Snapshot.Sensors.FirstOrDefault(v=>v.Id.Contains("cpu")&&v.Type=="Temperature"&&v.Value.HasValue&&v.Value.Value>0&&v.Value.Value<120);ring=t==null?"N/A":t.Value.Value.ToString("0")+"°";level=t==null?-1:t.Value.Value;secondary=Environment.ProcessorCount+" logical processors   ·   "+(t==null?"Temperature unavailable":"Live temperature");}series=(key=="CPU"?cpuHistory:gpuHistory).ToArray();foot="LIVE   ·   Utilization history";}else if(key=="Memory"){var m=Regex.Match(Metric("CPU","RAM"),@"([0-9.]+) / ([0-9.]+)");if(m.Success){primary=m.Groups[1].Value;unit="of "+m.Groups[2].Value+" GiB used";float used,total;if(float.TryParse(m.Groups[1].Value,out used)&&float.TryParse(m.Groups[2].Value,out total)&&total>0){level=100*used/total;ring=level.ToString("0")+"%";}}device="System memory";secondary="Capacity, speed and module details";}else if(key=="Storage"){tile.Capacity=capacitySnapshot;primary=capacitySnapshot==null?"—":StorageFormat.Size(capacitySnapshot.PhysicalBytes);unit="total installed storage";device="Physical drives";secondary="Used and free space across mounted volumes";ring="";}else if(key=="Network"){var m=Regex.Match(sources["Network"].Value,@"RX ([0-9.]+) KiB/s\s+TX ([0-9.]+)");if(m.Success){primary=m.Groups[1].Value;unit="KiB/s receiving";secondary="Sending "+m.Groups[2].Value+" KiB/s";}device=sources["Network"].Value.Split(new[]{"  "},StringSplitOptions.None)[0];ring="NET";}else{primary=sensorClient.Snapshot.Sensors.Count.ToString();unit="sensor channels";device="Hardware sensors";secondary="Temperatures, clocks, fans and power";ring="LIVE";}tile.Set(key,primary,unit,device.Trim(),secondary,foot,level,ring,series);}}
 }
}


